#!/usr/bin/env python3
"""Build the marketing-only v147 AI scroll repair from v146 staging.

Usage: python3 website_v147_patch.py --source BASELINE --output STAGING
The source is never modified. The output must not already exist.
"""

import argparse
import base64
import gzip
import hashlib
import json
from pathlib import Path
import shutil
import sys

BASELINE_TEXT_SHA256 = {'ai.html': 'ceb3e826fa54741feeac8dc05d5fb4d8fa52e535a510e0f41077104314bb6965', 'ai-v147.js': None, 'ai-scroll-v147.css': None}
OUTPUT_TEXT_SHA256 = {'ai.html': '94aed581b3b28b61ee643e6afe26a86ed2e86dbe7518b56e2950c761fe2c5aa5', 'ai-v147.js': 'f3f7711d528038fa64c9ba8883cb047b6f4e7841c850f8f8aa3e68d3743e4e82', 'ai-scroll-v147.css': '3ddcab648af3fb45367fcab3029aca32972308650d93cb7c92519318132d21f0'}
TEXT_PAYLOAD_GZIP_BASE64 = ''


VIDEO_PATH = 'video-preview/driveforma-owner-film-loop.mp4'
VIDEO_SHA256 = '6392202364f92fd0a64b276ac358573628aa03e866a3407fc7242cb7b608f2dd'
BASELINE_FILE_COUNT = 271


def digest(data):
    return hashlib.sha256(data).hexdigest()


def require(condition, message):
    if not condition:
        raise ValueError(message)


def tree_manifest(directory):
    result = {}
    for item in directory.rglob('*'):
        require(not item.is_symlink(), f'Symlinks are not allowed: {item.name}')
        if item.is_file():
            result[item.relative_to(directory).as_posix()] = digest(item.read_bytes())
    return result


def build_patch(source, output):
    source = source.resolve()
    output = output.resolve()
    require(source.is_dir(), 'The v146 staging source directory does not exist.')
    require(not output.exists(), 'The output must be a new staging directory.')
    require(source != output, 'The source and output must differ.')
    require(source not in output.parents, 'The output cannot be inside the source.')
    require(output not in source.parents, 'The source cannot be inside the output.')

    baseline = tree_manifest(source)
    require(len(baseline) == BASELINE_FILE_COUNT, 'The baseline file count is not v146.')
    for path, expected in BASELINE_TEXT_SHA256.items():
        require(baseline.get(path) == expected, f'Baseline text mismatch: {path}')
    require(baseline.get(VIDEO_PATH) == VIDEO_SHA256, 'The verified v146 header video is required.')

    texts = json.loads(gzip.decompress(base64.b64decode(TEXT_PAYLOAD_GZIP_BASE64, validate=True)))
    require(set(texts) == set(OUTPUT_TEXT_SHA256), 'Unexpected text payload paths.')
    encoded_texts = {}
    for path, content in texts.items():
        relative = Path(path)
        require(not relative.is_absolute() and '..' not in relative.parts, 'Invalid payload path.')
        data = content.encode('utf-8')
        require(digest(data) == OUTPUT_TEXT_SHA256[path], f'Text payload mismatch: {path}')
        encoded_texts[path] = data

    expected_changed = set(OUTPUT_TEXT_SHA256)
    expected_added = {path for path, value in BASELINE_TEXT_SHA256.items() if value is None}
    created = False
    try:
        shutil.copytree(source, output)
        created = True
        for path, data in encoded_texts.items():
            (output / path).write_bytes(data)
        actual = tree_manifest(output)
        require(set(actual) == set(baseline) | expected_added, 'The output file set changed unexpectedly.')
        for path, expected in OUTPUT_TEXT_SHA256.items():
            require(actual[path] == expected, f'Output text mismatch: {path}')
        require(actual.get(VIDEO_PATH) == VIDEO_SHA256, 'The header video was changed unexpectedly.')
        for path, expected in baseline.items():
            if path not in expected_changed:
                require(actual[path] == expected, f'Unchanged source was altered: {path}')
    except Exception:
        if created:
            shutil.rmtree(output)
        raise

    return {
        'release': 'v147',
        'result': 'PASS',
        'files': len(actual),
        'changed': sorted(expected_changed),
        'preservedExistingFiles': len(baseline) - len(expected_changed - expected_added),
        'headerVideoSha256': VIDEO_SHA256,
        'sourceModified': False,
        'publication': 'Staging only. The caller must publish after this command succeeds.',
    }


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--source', type=Path, required=True)
    parser.add_argument('--output', type=Path, required=True)
    args = parser.parse_args()
    try:
        result = build_patch(args.source, args.output)
    except Exception as error:
        print(f'Website staging patch failed: {error}', file=sys.stderr)
        return 1
    print(json.dumps(result, sort_keys=True))
    return 0


if __name__ == '__main__':
    raise SystemExit(main())
